/** Một dòng → mảng 65 ô theo HEADER_THAT, ô vắng = ''. */
export function oCuaDong(d: DongThat, header: readonly string[] = HEADER_THAT): (string | number)[] {
  return header.map((k) => d[k] ?? "");
}

/** Dựng .xlsx (1 sheet, dòng 1 là header) và đóng gói lại bằng data descriptor như file ngân hàng. */
export async function dungXlsxThat(
  dong: readonly DongThat[],
  opts: { header?: readonly string[]; tenSheet?: string } = {},
): Promise<Uint8Array> {
  const header = opts.header ?? HEADER_THAT;
  const ws = XLSX.utils.aoa_to_sheet([[...header], ...dong.map((d) => oCuaDong(d, header))]);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, opts.tenSheet ?? "29092026_TXN_000");
  const thuong = XLSX.write(wb, { type: "array", bookType: "xlsx" }) as ArrayBuffer;
  const trong = await JSZip.loadAsync(thuong);
  const lai = new JSZip();
  for (const [ten, f] of Object.entries(trong.files)) {
    if (!f.dir) lai.file(ten, await f.async("uint8array"), { createFolders: false });
  }
  return lai.generateAsync({ type: "uint8array", compression: "DEFLATE", streamFiles: true });
}

/** Dựng .zip như file tải về: `<thuMuc>/29092026_TXN_000.xlsx`, `_001`… mỗi phần một file. */
export async function dungZipThat(thuMuc: string, cacPhan: readonly (readonly DongThat[])[]): Promise<Uint8Array> {
  const zip = new JSZip();
  zip.folder(thuMuc);
  for (let i = 0; i < cacPhan.length; i++) {
    const ten = `${thuMuc}/29092026_TXN_${String(i).padStart(3, "0")}.xlsx`;
    zip.file(ten, await dungXlsxThat(cacPhan[i]!));
  }
  return zip.generateAsync({ type: "uint8array", compression: "DEFLATE", streamFiles: true });
}
